var a=88;var o=[{id:`cooking-088-01`,theoryId:88,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which meat cut often benefits most from a long gentle slow-cook?`,ua:`Який шматок м’яса часто найбільше виграє від тривалого повільного приготування?`},explanation:{en:`Connective tissue can gradually soften under prolonged moist heat.`,ua:`Сполучна тканина може поступово розм’якшуватися за тривалого вологого нагрівання.`},options:[{id:`a`,text:{en:`Collagen-rich beef shoulder`,ua:`Яловича лопатка з великою кількістю колагену`}},{id:`b`,text:{en:`Thin delicate fish fillet`,ua:`Тонке ніжне рибне філе`}},{id:`c`,text:{en:`Already cooked tender lettuce`,ua:`Уже приготований ніжний салат`}}],answer:{optionIds:[`a`]}},{id:`cooking-088-02`,theoryId:88,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`A slow cooker’s keep-warm setting is suitable for cooking raw poultry from the start.`,ua:`Режим «Підтримання тепла» у мультиварці підходить для приготування сирої курятини з початку.`},explanation:{en:`Keep-warm is intended for holding already safely cooked food, not cooking raw meat.`,ua:`Режим підтримання тепла призначений для вже безпечно приготованої їжі, а не для сирого м’яса.`},answer:{value:!1}},{id:`cooking-088-03`,theoryId:88,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match the slow-cooking practice to its purpose.`,ua:`Поєднайте практику повільного приготування з метою.`},explanation:{en:`Slow cooking still needs safe preparation and validated endpoints.`,ua:`Повільне приготування все одно вимагає безпечної підготовки й перевіреної готовності.`},leftItems:[{id:`l1`,text:{en:`Thaw meat safely first`,ua:`Спершу безпечно розморозити м’ясо`}},{id:`l2`,text:{en:`Keep lid on`,ua:`Тримати кришку закритою`}},{id:`l3`,text:{en:`Check final internal temperature`,ua:`Перевірити кінцеву внутрішню температуру`}}],rightItems:[{id:`r3`,text:{en:`Verify safe doneness`,ua:`Підтвердити безпечну готовність`}},{id:`r2`,text:{en:`Limit heat and moisture loss`,ua:`Обмежити втрати тепла та вологи`}},{id:`r1`,text:{en:`Avoid prolonged warming of frozen raw center`,ua:`Уникнути тривалого прогрівання замороженої сирої середини`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-088-04`,theoryId:88,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`You want to reheat refrigerated leftover stew in a slow cooker from cold. What is safer?`,ua:`Хочете розігріти холодне рагу з холодильника в мультиварці. Що безпечніше?`},explanation:{en:`Slow cookers are not recommended for reheating cold leftovers; reheat promptly with another method.`,ua:`Мультиварку не рекомендують для розігрівання холодних залишків; потрібен швидкий розігрів іншим методом.`},options:[{id:`a`,text:{en:`Reheat rapidly on stovetop to 74°C (165°F), then use keep-warm for holding`,ua:`Швидко розігріти на плиті до 74°C (165°F), а потім підтримувати тепло`}},{id:`b`,text:{en:`Leave cold leftovers on keep-warm for many hours`,ua:`Залишити холодні залишки на режимі підігріву на багато годин`}},{id:`c`,text:{en:`Let leftovers warm overnight unplugged`,ua:`Залишити залишки нагріватися всю ніч без увімкнення`}}],answer:{optionIds:[`a`]}},{id:`cooking-088-05`,theoryId:88,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which slow-cooker preparation is unsafe?`,ua:`Яка підготовка до повільного приготування небезпечна?`},explanation:{en:`Slow warming of a frozen core can create unsafe time-temperature exposure.`,ua:`Повільне прогрівання замороженої середини може створити небезпечні умови часу й температури.`},options:[{id:`a`,text:{en:`Thaw frozen meat in a refrigerator`,ua:`Розморозити м’ясо в холодильнику`}},{id:`b`,text:{en:`Use the manufacturer’s recommended fill level`,ua:`Дотриматися рекомендованого рівня заповнення`}},{id:`c`,text:{en:`Put a large frozen raw roast in a slow cooker and assume it heats safely`,ua:`Покласти великий заморожений сирий шматок у мультиварку й вважати, що він гарантовано безпечно прогріється`}}],answer:{optionIds:[`c`]}}];var i={theoryId:88,exercises:o};export{i as default,o as exercises,a as theoryId};